async function loadGoogleAssets(userId){let row=await getGoogleIntegration(userId);if(!row?.connected)throw Object.assign(new Error('Google Ads não está conectado.'),{status:409});let m={...(row.metadata||{}),userId},token=await googleAccessToken(m),list=await googleAdsFetch('/customers:listAccessibleCustomers',token),ids=(list.resourceNames||[]).map(x=>String(x).split('/').pop()).filter(Boolean),customers=[];for(let id of ids){let info={id,name:'Conta Google Ads '+id,currency:'',timezone:'',manager:false};try{let q='SELECT customer.id, customer.descriptive_name, customer.currency_code, customer.time_zone, customer.manager FROM customer LIMIT 1',data=await googleAdsFetch(`/customers/${id}/googleAds:search`,token,{method:'POST',body:{query:q}}),c=data.results?.[0]?.customer||{};info={id:String(c.id||id),name:c.descriptiveName||info.name,currency:c.currencyCode||'',timezone:c.timeZone||'',manager:!!c.manager}}catch{}customers.push(info)}return {connectedAt:m.connectedAt||'',customers,selected:{customerId:m.selectedCustomerId||''},apiVersion:GOOGLE_ADS_API_VERSION}}

