async function init(){if(!pool)return;await pool.query(`CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY,name text NOT NULL,email text UNIQUE NOT NULL,role text NOT NULL DEFAULT 'user',password_salt text NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_login_at timestamptz);CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);CREATE TABLE IF NOT EXISTS oauth_states(state_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider text NOT NULL,expires_at timestamptz NOT NULL);CREATE TABLE IF NOT EXISTS x_oauth_requests(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_secret_enc text NOT NULL,expires_at timestamptz NOT NULL);CREATE TABLE IF NOT EXISTS businesses(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,data jsonb NOT NULL DEFAULT '{}'::jsonb);CREATE TABLE IF NOT EXISTS brands(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,data jsonb NOT NULL DEFAULT '{}'::jsonb);CREATE TABLE IF NOT EXISTS campaigns(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS competitors(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS decisions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS integrations(user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider text NOT NULL,connected boolean NOT NULL DEFAULT false,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,PRIMARY KEY(user_id,provider));CREATE TABLE IF NOT EXISTS creatives(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,campaign_id uuid REFERENCES campaigns(id) ON DELETE CASCADE,source text NOT NULL DEFAULT 'ai',asset_url text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS campaign_results(id bigserial PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,provider text NOT NULL,metric_date date NOT NULL,spend numeric(14,2) DEFAULT 0,impressions bigint DEFAULT 0,clicks bigint DEFAULT 0,contacts bigint DEFAULT 0,sales bigint DEFAULT 0,revenue numeric(14,2) DEFAULT 0,raw jsonb NOT NULL DEFAULT '{}'::jsonb,UNIQUE(campaign_id,provider,metric_date));CREATE INDEX IF NOT EXISTS idx_campaigns_user ON campaigns(user_id);CREATE INDEX IF NOT EXISTS idx_results_date ON campaign_results(campaign_id,metric_date DESC);`);for(let p of INTEGRATION_PROVIDERS)await pool.query('INSERT INTO integrations(user_id,provider) SELECT id,$1 FROM users ON CONFLICT DO NOTHING',[p]);await ensureAdmin()}
async function userEmail(email){return pool?(await pool.query('SELECT * FROM users WHERE email=$1',[email])).rows[0]||null:mem.users.find(x=>x.email===email)||null}async function userId(id){return pool?(await pool.query('SELECT * FROM users WHERE id=$1',[id])).rows[0]||null:mem.users.find(x=>x.id===id)||null}
async function seedRows(id){let d=defaults();if(pool){await pool.query('INSERT INTO businesses(user_id,data) VALUES($1,$2) ON CONFLICT DO NOTHING',[id,d.business]);await pool.query('INSERT INTO brands(user_id,data) VALUES($1,$2) ON CONFLICT DO NOTHING',[id,d.brand]);for(let p of INTEGRATION_PROVIDERS)await pool.query('INSERT INTO integrations(user_id,provider) VALUES($1,$2) ON CONFLICT DO NOTHING',[id,p])}else{mem.business.set(id,d.business);mem.brand.set(id,d.brand);for(let p of INTEGRATION_PROVIDERS)mem.integrations.push({user_id:id,provider:p,connected:false})}}
async function addUser(name,email,pass,role='user'){let hp=hash(pass),u={id:uid(),name,email,role,password_salt:hp.salt,password_hash:hp.hash,created_at:now(),last_login_at:now()};if(pool)await pool.query('INSERT INTO users(id,name,email,role,password_salt,password_hash,created_at,last_login_at) VALUES($1,$2,$3,$4,$5,$6,$7,$8)',[u.id,u.name,u.email,u.role,u.password_salt,u.password_hash,u.created_at,u.last_login_at]);else mem.users.push(u);await seedRows(u.id);return u}
async function ensureAdmin(){let e=String(process.env.ADMIN_EMAIL||'').trim().toLowerCase(),p=String(process.env.ADMIN_PASSWORD||'');if(!e||p.length<8){if(pool)console.warn('Defina ADMIN_EMAIL e ADMIN_PASSWORD no Railway para criar o Administrador Geral.');return}if(!await userEmail(e))await addUser('Administrador Geral',e,p,'admin')}
const cookies=req=>Object.fromEntries((req.headers.cookie||'').split(';').map(x=>x.trim().split('=')).filter(x=>x[0]));
async function session(id){let token=crypto.randomBytes(32).toString('hex'),h=crypto.createHash('sha256').update(token).digest('hex'),exp=new Date(Date.now()+2592e6);if(pool)await pool.query('INSERT INTO sessions(token_hash,user_id,expires_at) VALUES($1,$2,$3)',[h,id,exp]);else mem.sessions.set(h,{id,exp});return token}async function auth(req){let t=cookies(req).session;if(!t)return null;let h=crypto.createHash('sha256').update(t).digest('hex'),id;if(pool)id=(await pool.query('SELECT user_id FROM sessions WHERE token_hash=$1 AND expires_at>now()',[h])).rows[0]?.user_id;else{let s=mem.sessions.get(h);if(s&&s.exp>new Date())id=s.id}return id?userId(id):null}
